"use client";import {useState} from 'react';export default function LessonComplete({lessonId}:{lessonId:string}){const[msg,setMsg]=useState('');return <><button onClick={async()=>{const r=await fetch('/api/lessons/progress',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lessonId})});setMsg(r.ok?'Materi ditandai selesai':'Login diperlukan atau terjadi kesalahan')}}>Tandai selesai</button><p>{msg}</p></>}